// GameAttributeSet.h
#pragma once
#include "CoreMinimal.h"
#include "AttributeSet.h"
#include "AbilitySystemComponent.h"
#include "GameAttributeSet.generated.h"

#define GAME_ATTRIBUTE_ACCESSORS(ClassName, PropertyName) \
    GAMEPLAYATTRIBUTE_PROPERTY_GETTER(ClassName, PropertyName) \
    GAMEPLAYATTRIBUTE_VALUE_GETTER(PropertyName) \
    GAMEPLAYATTRIBUTE_VALUE_SETTER(PropertyName) \
    GAMEPLAYATTRIBUTE_VALUE_INITTER(PropertyName)

UCLASS()
class GAMEFORGE_API UGameAttributeSet_13 : public UAttributeSet
{
    GENERATED_BODY()
public:
    UGameAttributeSet_13();
    virtual void GetLifetimeReplicatedProps(TArray<FLifetimeProperty>& OutLifetimeProps) const override;
    virtual void PreAttributeChange(const FGameplayAttribute& Attribute, float& NewValue) override;
    virtual void PostGameplayEffectExecute(const FGameplayEffectModCallbackData& Data) override;

    UPROPERTY(BlueprintReadOnly, ReplicatedUsing=OnRep_Poise, Category="Attributes")
    FGameplayAttributeData Poise;
    GAME_ATTRIBUTE_ACCESSORS(UGameAttributeSet_13, Poise)

    UPROPERTY(BlueprintReadOnly, ReplicatedUsing=OnRep_MaxPoise, Category="Attributes")
    FGameplayAttributeData MaxPoise;
    GAME_ATTRIBUTE_ACCESSORS(UGameAttributeSet_13, MaxPoise)

protected:
    UFUNCTION()
    virtual void OnRep_Poise(const FGameplayAttributeData& OldPoise);
    UFUNCTION()
    virtual void OnRep_MaxPoise(const FGameplayAttributeData& OldMaxPoise);
};

// GameAttributeSet.cpp
#include "GameAttributeSet.h"
#include "Net/UnrealNetwork.h"
#include "GameplayEffectExtension.h"

UGameAttributeSet_13::UGameAttributeSet_13()
{
    InitPoise(100.0f);
    InitMaxPoise(100.0f);
}

void UGameAttributeSet_13::GetLifetimeReplicatedProps(TArray<FLifetimeProperty>& OutLifetimeProps) const
{
    Super::GetLifetimeReplicatedProps(OutLifetimeProps);
    DOREPLIFETIME_CONDITION_NOTIFY(UGameAttributeSet_13, Poise, COND_None, REPNOTIFY_Always);
    DOREPLIFETIME_CONDITION_NOTIFY(UGameAttributeSet_13, MaxPoise, COND_None, REPNOTIFY_Always);
}

void UGameAttributeSet_13::PreAttributeChange(const FGameplayAttribute& Attribute, float& NewValue)
{
    Super::PreAttributeChange(Attribute, NewValue);
    if (Attribute == GetPoiseAttribute())
    {
        NewValue = FMath::Clamp(NewValue, 0.0f, GetMaxPoise());
    }
}

void UGameAttributeSet_13::PostGameplayEffectExecute(const FGameplayEffectModCallbackData& Data)
{
    Super::PostGameplayEffectExecute(Data);
    if (Data.EvaluatedData.Attribute == GetPoiseAttribute())
    {
        SetPoise(FMath::Clamp(GetPoise(), 0.0f, GetMaxPoise()));
    }
}

void UGameAttributeSet_13::OnRep_Poise(const FGameplayAttributeData& OldPoise)
{
    GAMEPLAYATTRIBUTE_REPNOTIFY(UGameAttributeSet_13, Poise, OldPoise);
}

void UGameAttributeSet_13::OnRep_MaxPoise(const FGameplayAttributeData& OldMaxPoise)
{
    GAMEPLAYATTRIBUTE_REPNOTIFY(UGameAttributeSet_13, MaxPoise, OldMaxPoise);
}

