        // Health decay
        stats.Health -= stats.DecayRate * DeltaTime;

        // Spatial movement
        float3 toTarget = target.TargetPosition - transform.Position;
        float distSq = math.lengthsq(toTarget);
        if (distSq > 0.01f)
